            parts = listOf(
                StoryPart(1, "A Notebook on the Counter", listOf(
                    "During a school journalism assignment, Efe visited the town market with a teacher to write about its weekly market day. At a public information desk, she noticed an old notebook filled with dates, weather notes, and lists of community events. The market coordinator explained that it was a volunteer record, not a public directory of traders.",
